action.code:
randomgen rng(seed);
double width = b - a;
double area = width * fmax;
int hits = 0;

for (int i = 0; i < n_points; ++i) {
    double x = rng.uniform(a, b);
    double y = rng.uniform(0.0, fmax);
    if (y <= f(x)) {
        hits++;
    }
}

return static_cast<double>(hits) * area / n_points;

